use serde::{Deserialize, Serialize};

use crate::models::{OpenAiCompletionTokensDetails, OpenAiPromptTokensDetails};

/// OpenAI-compatible open ai token usage schema exposed by Claw Router.
#[derive(Serialize, Deserialize, Debug, Clone, Default)]
pub struct OpenAiTokenUsage {
    /// Number of output tokens generated by the model.
    pub completion_tokens: i64,

    /// Completion tokens details field on the open ai token usage, using the open ai completion tokens details module.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub completion_tokens_details: Option<OpenAiCompletionTokensDetails>,

    /// Number of input tokens billed for the request.
    pub prompt_tokens: i64,

    /// Prompt tokens details field on the open ai token usage, using the open ai prompt tokens details module.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub prompt_tokens_details: Option<OpenAiPromptTokensDetails>,

    /// Total input and output token count.
    pub total_tokens: i64,
}
